"""Support for classes generated by `pyquickbase codegen`. No network access."""

from collections.abc import Iterable, Sequence
from dataclasses import dataclass, fields
from decimal import Decimal
from typing import Any, ClassVar, Generic, Self, TypeVar

from ._models import Field, Record
from ._query import F
from .errors import InvalidResponseError, SchemaMismatchError

_BUILT_IN_FIELDS = 5
WRITABLE_TYPES = {
    "text",
    "text-multiple-choice",
    "text-multi-line",
    "rich-text",
    "numeric",
    "currency",
    "rating",
    "percent",
    "multitext",
    "email",
    "url",
    "duration",
    "date",
    "timestamp",
    "timeofday",
    "checkbox",
    "user",
    "multiuser",
    "phone",
    "file",
}


def is_writable(field: Field) -> bool:
    """Whether a field can be written. Types we haven't confirmed count as read-only."""
    return field.mode is None and field.id > _BUILT_IN_FIELDS and field.type in WRITABLE_TYPES


def read_as(field: Field) -> str:
    """How a generated class converts a field's value, as a query returns every number as a float.

    `decimal_places` is only how a number is displayed, so `TypedRecord` still checks each value.
    """
    if field.type == "currency":
        return "decimal"
    if field.type == "numeric" and (field.is_foreign_key or field.decimal_places == 0):
        return "int"
    return ""


class Unset:
    """The type of `UNSET`, which means "leave this field alone", unlike None, which clears it."""

    __slots__ = ()

    def __repr__(self) -> str:
        return "UNSET"


UNSET = Unset()


class TypedField(F):
    """A field of a generated class, usable in queries like `F`. `desc` sorts it descending."""

    __slots__ = ()

    @property
    def id(self) -> int:
        return self._field  # pyright: ignore[reportReturnType]

    @property
    def desc(self) -> int:
        return -self.id


OrderBy = TypedField | int | Sequence[TypedField | int] | None


def order_refs(order_by: OrderBy) -> list[int] | None:
    """Turn `order_by` into field IDs, where a negative ID sorts descending."""
    if order_by is None:
        return None
    refs = [order_by] if isinstance(order_by, TypedField | int) else order_by
    return [ref.id if isinstance(ref, TypedField) else ref for ref in refs]


@dataclass(frozen=True, slots=True)
class Column:
    """How a generated attribute maps to a field. `field_type` is what codegen saw.

    `read_as` is `int` or `decimal` when a number gets converted, and empty otherwise.
    """

    name: str
    id: int
    field_type: str
    writable: bool
    label: str
    read_as: str = ""


R = TypeVar("R", bound="TypedRecord")


class Row(dict[int, Any], Generic[R]):
    """Values to write, by field ID, from a generated class's `new()` or `change()`.

    It's tied to its class, so a type checker refuses a row meant for another table.
    """


def _converted(column: Column, value: Any) -> Any:
    if value is None or not column.read_as:
        return value
    if column.read_as == "decimal":
        # str() gives the shortest text for the float, which is the exact cents Quickbase holds.
        return Decimal(str(value))
    if value != int(value):
        # Rounding could silently change an amount. The value isn't shown, as it may be sensitive.
        raise InvalidResponseError(
            f"Field {column.label!r} is set to no decimal places, so it was generated as an int, "
            "but a record holds a fraction. Quickbase only uses that setting for display. Fix the "
            "record, or change the setting and run `pyquickbase codegen` again."
        )
    return int(value)


class TypedRecord:
    """The base of generated classes. One instance is one record, with a type for each field.

    `repr` shows only the record's shape, because values may be sensitive and reprs end up in logs.
    """

    __slots__ = ()
    # Generated files use these, `_row`, and positional `Column(...)`, and must keep working through
    # 1.x, so any new `Column` field needs a default. tests/_async/test_generated_contract.py checks
    # this.
    # `_row` can't collide with a field, because generated attribute names never start with `_`.
    __table_id__: ClassVar[str]
    __columns__: ClassVar[tuple[Column, ...]]

    @classmethod
    def from_record(cls, record: Record) -> Self:
        """Build an instance from a record that holds every column."""
        try:
            return cls(
                **{column.name: _converted(column, record[column.id]) for column in cls.__columns__}
            )
        except KeyError as exc:
            raise InvalidResponseError(
                f"A {cls.__name__} record is missing a field. A report may have left it out, or "
                "your access may not include it."
            ) from exc

    @classmethod
    def _row(cls, values: dict[str, Any]) -> Row[Self]:
        ids = {column.name: column.id for column in cls.__columns__}
        return Row({ids[name]: value for name, value in values.items() if value is not UNSET})

    def __repr__(self) -> str:
        record_id = getattr(self, "id", None)
        return f"{type(self).__name__}(id={record_id!r}, fields={len(fields(self))})"  # pyright: ignore[reportArgumentType]


def column_ids(model: type[TypedRecord]) -> list[int]:
    return [column.id for column in model.__columns__]


def schema_problems(model: type[TypedRecord], current: Iterable[Field]) -> list[str]:
    """Compare a generated class with the table as it is now."""
    by_id = {field.id: field for field in current}
    problems: list[str] = []
    for column in model.__columns__:
        field = by_id.get(column.id)
        if field is None:
            # Quickbase leaves out fields a role can't see, so these look the same as deleted ones.
            problems.append(
                f"{column.name} (field {column.id}) no longer exists, or this token can't see it"
            )
        elif field.type != column.field_type:
            problems.append(f"{column.name} was {column.field_type} and is now {field.type}")
        elif column.read_as and read_as(field) != column.read_as:
            problems.append(f"{column.name} is no longer read as {column.read_as}")
        elif column.writable and not is_writable(field):
            # Only this direction. A later SDK can confirm more writable types, which mustn't fail
            # a class generated before that, and a class that won't write a field is still safe.
            problems.append(f"{column.name} is now read-only")
    return problems


def raise_for_problems(model: type[TypedRecord], problems: list[str]) -> None:
    if problems:
        raise SchemaMismatchError(
            f"{model.__name__} doesn't match its table: {'; '.join(problems)}. "
            "Run `pyquickbase codegen` again."
        )
